"""The frozen reference reproduces goldens generated by the real cfb-rankings code (@ 40a6b4f).

Tolerances (requirements.yaml, technical): objective and each of the four terms
within 1e-6 relative (absolute floor 1e-9 for terms that are ~0); ratings within
1e-3 absolute where the scenario's solution is unique, both the raw solve and the
published (shifted) ratings. Ratings of teams listed in `non_unique_teams` (zero
losses at lambda = 0: a flat direction) are not compared; the published shift is
compared because the lowest team is unique in every scenario (asserted by the
generator). The solver is the one the goldens recorded.
"""
import cvxpy as cp
import pytest

from tests.reference import football_reference as ref
from tests.reference.fixture_io import load_fixture, load_goldens

GOLD = load_goldens()
GAMES, TEAMS = load_fixture()
SCENARIOS = list(GOLD["scenarios"])
SOLVER = GOLD["prior_season"]["solver"]

REL = 1e-6
ABS_FLOOR = 1e-9
RATING_ABS = 1e-3


def approx(x):
    return pytest.approx(x, rel=REL, abs=ABS_FLOOR)


def assert_solution_matches(details, gold):
    assert details["objective"] == approx(gold["objective"])
    assert details["margin_penalty"] == approx(gold["terms"]["margin"])
    assert details["loss_rate_penalty"] == approx(gold["terms"]["loss_rate"])
    assert details["fcs_loss_penalty"] == approx(gold["terms"]["fcs_loss"])
    assert details["prior_term"] == approx(gold["terms"]["prior"])
    assert details["solver"] == gold["solver"]


def skipped(gold):
    skip = set(gold["non_unique_teams"])
    # the dummy rating is a flat direction when no lower-division loss is active at the solution
    if gold["main"]["terms"]["fcs_loss"] == 0:
        skip.add("fcs")
    return skip


def assert_ratings_match(ratings, gold_ratings, skip=()):
    assert set(ratings) == set(gold_ratings)
    for team, value in gold_ratings.items():
        if team in skip:
            continue
        assert ratings[team] == pytest.approx(value, abs=RATING_ABS), team


def test_goldens_recorded_the_pinned_stack():
    v = GOLD["provenance"]["versions"]
    assert GOLD["provenance"]["commit"] == "40a6b4f"
    assert v["cvxpy"] == cp.__version__ == "1.8.1"
    assert SOLVER == GOLD["provenance"]["default_solver_for_main_problem"] == "OSQP"


def test_prior_season_solve_matches_football():
    gold = GOLD["prior_season"]
    ratings, details = ref.get_prior_ratings(GAMES, TEAMS, gold["year"], solver=SOLVER)
    assert_solution_matches(details, {**gold, "terms": {**gold["terms"], "prior": 0.0}})
    assert details["r_fcs"] == pytest.approx(gold["r_fcs"], abs=RATING_ABS)
    assert details["k_margin"] == pytest.approx(gold["k_margin"], rel=1e-15)
    # the prior model returns its solve RAW (never shifted): negative ratings included
    assert_ratings_match(ratings, gold["ratings"] | {"fcs": gold["r_fcs"]})
    assert min(ratings.values()) < 0


@pytest.mark.parametrize("name", SCENARIOS)
def test_assembly_matches_football(name):
    gold = GOLD["scenarios"][name]
    teams, games, fcs_losses, records, connectivity = ref.get_data_by_year_up_to_week(
        GAMES, TEAMS, gold["year"], gold["week"])
    a = gold["assembled"]
    assert teams == a["teams"]
    assert [list(g) for g in games] == a["games"]
    assert [list(x) for x in fcs_losses] == a["fcs_losses"]
    assert {t: list(r) for t, r in records.items()} == a["records"]
    assert connectivity == a["connectivity"]


@pytest.mark.parametrize("name", SCENARIOS)
def test_scenario_matches_football(name):
    gold = GOLD["scenarios"][name]
    ratings, records, details = ref.get_ratings(GAMES, TEAMS, gold["year"], gold["week"], solver=SOLVER)
    assert_solution_matches(details, gold["main"])
    assert {t: list(r) for t, r in records.items()} == gold["records"]
    assert details["lambda"] == gold["lambda"]
    assert details["k_margin"] == pytest.approx(gold["main"]["k_margin"], rel=1e-15)
    skip = skipped(gold)
    raw = details["raw_ratings"]
    assert raw["fcs"] == pytest.approx(details["r_fcs"])
    assert_ratings_match(raw, gold["raw_ratings"], skip)
    assert_ratings_match(ratings, gold["ratings"], skip)


@pytest.mark.parametrize("name", SCENARIOS)
def test_published_ratings_are_the_raw_solve_shifted_so_the_lowest_team_reads_0_01(name):
    gold = GOLD["scenarios"][name]
    ratings, _, details = ref.get_ratings(GAMES, TEAMS, gold["year"], gold["week"], solver=SOLVER)
    raw = details["raw_ratings"]
    teams = {t: v for t, v in raw.items() if t != "fcs"}
    lowest = min(teams, key=teams.get)
    assert lowest == gold["lowest_team"]
    assert ratings[lowest] == pytest.approx(0.01, abs=1e-12)
    shift = 0.01 - raw[lowest]
    assert shift == pytest.approx(gold["display_shift"], abs=RATING_ABS)
    assert all(ratings[t] == pytest.approx(raw[t] + shift, abs=1e-12) for t in raw)  # the dummy moves too
    assert raw[lowest] < 0  # no floor: the solve runs below zero at the bottom


def test_the_lowest_team_and_so_the_shift_changes_between_scenarios():
    lowest = {n: GOLD["scenarios"][n]["lowest_team"] for n in SCENARIOS}
    assert len(set(lowest.values())) >= 3, lowest
    assert lowest["w03"] != lowest["w06"]


@pytest.mark.parametrize("name", SCENARIOS)
def test_passing_priors_in_equals_computing_them(name):
    gold = GOLD["scenarios"][name]
    prior = GOLD["prior_season"]["ratings"]
    ratings, _, details = ref.get_ratings(GAMES, TEAMS, gold["year"], gold["week"], prior_ratings=prior, solver=SOLVER)
    assert details["objective"] == approx(gold["main"]["objective"])
    assert_ratings_match(ratings, gold["ratings"], set(gold["non_unique_teams"]) | {"fcs"})
    assert "Oakhurst" not in prior  # new FBS team: the default prior 1 is applied inside get_ratings


@pytest.mark.parametrize("name", SCENARIOS)
def test_default_solver_is_the_goldens_solver(name):
    gold = GOLD["scenarios"][name]
    ratings, _, details = ref.get_ratings(GAMES, TEAMS, gold["year"], gold["week"])
    assert details["solver"] == SOLVER
    assert details["objective"] == approx(gold["main"]["objective"])


@pytest.mark.parametrize("name", SCENARIOS)
def test_unique_ratings_do_not_depend_on_the_solver(name):
    """Evidence that compared ratings are unique: CLARABEL (interior point) lands on the same ratings as OSQP."""
    gold = GOLD["scenarios"][name]
    ratings, _, details = ref.get_ratings(GAMES, TEAMS, gold["year"], gold["week"], solver="CLARABEL")
    skip = skipped(gold)
    assert_ratings_match(details["raw_ratings"], gold["raw_ratings"], skip)
    assert_ratings_match(ratings, gold["ratings"], skip)  # the shift is set by a unique (lowest) team


def test_quirk_week_none_raises_like_football():
    q = GOLD["quirks"]["week_none"]
    with pytest.raises(TypeError, match="not supported"):
        ref.get_ratings(GAMES, TEAMS, 2024, None, solver=SOLVER)
    assert q["raised"] == "TypeError"


def test_quirk_week_zero_reads_every_game_and_applies_lambda():
    q = GOLD["quirks"]["week_zero"]
    ratings, _, details = ref.get_ratings(GAMES, TEAMS, 2024, 0, solver=SOLVER)
    assert details["lambda"] == pytest.approx(7 / 700)
    assert_solution_matches(details, q)
    assert_ratings_match(ratings, q["ratings"])
    assert_ratings_match(details["raw_ratings"], q["raw_ratings"])


def test_quirk_no_prior_season_data_raises_like_football():
    q = GOLD["quirks"]["no_prior_season_data"]
    with pytest.raises(ValueError, match="empty"):
        ref.get_ratings(GAMES, TEAMS, 2023, 15, solver=SOLVER)
    assert q["raised"] == "ValueError"


def test_quirk_tie_is_scored_as_an_away_win():
    q = GOLD["quirks"]["tie_game"]
    extra = {k: v for k, v in q["extra_game"].items()}
    games = GAMES.copy()
    games.loc[len(games)] = extra
    games["home_score"] = games["home_score"].astype("Int64")
    ratings, records, details = ref.get_ratings(games, TEAMS, q["year"], q["week"], solver=SOLVER)
    assert_solution_matches(details, q)
    assert {t: list(r) for t, r in records.items()} == q["records"]
    # the tied pair is recorded as a win for the away team, and no tie is ever counted
    assert all(r[2] == 0 for r in records.values())
    skip = set(GOLD["scenarios"]["w10"]["non_unique_teams"]) | {"fcs"}
    assert_ratings_match(ratings, q["ratings"], skip)
    assert_ratings_match(details["raw_ratings"], q["raw_ratings"], skip)


def test_prior_without_lower_division_losses_now_solves_like_football():
    """Crashed at 8ab8201 (unguarded empty sum); guarded at 40a6b4f."""
    q = GOLD["quirks"]["prior_without_fcs_losses"]
    games = GAMES[~GAMES["id"].isin(q["dropped_game_ids"])]
    ratings, details = ref.get_prior_ratings(games, TEAMS, 2023, solver=SOLVER)
    assert q["raised"] is None
    assert_solution_matches(details, {**q["prior"], "terms": {**q["prior"]["terms"], "prior": 0.0}})
    assert details["fcs_loss_penalty"] == 0.0
    assert_ratings_match(ratings, q["result"], {"fcs"})  # no lower-division loss: the dummy is flat


def test_quirk_season_without_d1_games_still_raises_after_solving():
    """The margin and loss-rate sums are still unguarded at 40a6b4f (only the FCS sums are)."""
    q = GOLD["quirks"]["no_d1_games"]
    games = GAMES[~GAMES["id"].isin(q["dropped_game_ids"])]
    with pytest.raises(AttributeError, match="'int' object has no attribute 'value'"):
        ref.get_ratings(games, TEAMS, 2024, 15, solver=SOLVER)
    assert q["raised"] == "AttributeError"
